window.RP_SESSION={"id":"S-d36152d5b46c","messages":[{"id":"RP-III-0092168","time":"2026-05-06T01:45:00+09:00","room":"RP III","name":"리스 / 제이","profile":"루체","identity":"reviewed","type":"dialogue","body":"이곳은 스텔라의 집무실, 책상 위","characters":["P-cf5685fee62d","P-542abe61bdc5"]},{"id":"RP-III-0092169","time":"2026-05-06T01:45:00+09:00","room":"RP III","name":"리스 / 제이","profile":"루체","identity":"reviewed","type":"dialogue","body":"종이 한장이 새롭게 놓여져있다","characters":["P-cf5685fee62d","P-542abe61bdc5"]},{"id":"RP-III-0092170","time":"2026-05-06T01:46:00+09:00","room":"RP III","name":"리스 / 제이","profile":"루체","identity":"reviewed","type":"dialogue","body":"[휴가감\n\n-리스]","characters":["P-cf5685fee62d","P-542abe61bdc5"]},{"id":"RP-III-0092171","time":"2026-05-06T01:46:00+09:00","room":"RP III","name":"리스 / 제이","profile":"루체","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-cf5685fee62d","P-542abe61bdc5"]},{"id":"RP-III-0092172","time":"2026-05-06T01:46:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"다음을 기대할게..!","characters":[]},{"id":"RP-III-0092173","time":"2026-05-06T02:12:00+09:00","room":"RP III","name":"리스 / 제이","profile":"루체","identity":"reviewed","type":"dialogue","body":"다그닥 다그닥\n덜컹덜컹\n\n짐마차는 나름 요란한 소리를 내며 달렸다.\n\n리스는, 아니 이제…\n\n“음… 무슨 이름으로 하지”\n\n로즈? 구닥다리야. 아멜리아…는 길어서 마음에 안들고.\n제이. 제이가 편하겠다.\n\n마차에 누워 하늘을 올려다보면 드높은 하늘엔 드문드문 구름만 떠나간다.\n새로이 모험을 시작한 제이는 제 이름이 퍽 마음에 들었다.\n정확히는 이름이 마음에 든게 아니다.\n‘새로운'이름에 아무도 자신을 모르는 ‘새로운'공간이 마음에 든거겠지.\n\n구름 아래 느긋하게 홀로 나는 새를 보면 드는 생각이다.\n인연이란 것도 끈과 같아서, 서로 얽히다 보면 풀 수 없는 매듭이 되어가버린다.\n자유로운 바람은 매듭에 묶여 살순 없는법 아닌가.\n\n그래서 도망쳤다.\n시원하게.\n종이한장 놔두고.\n\n그것도 제이 나름의 장족의 발전이라 할수 있다.\n돌아올 생각은 했지 않았는가.\n제이는 본디 돌아보지 않는 인간이라.\n\n그것도 그것 나름의 성장이라.\n\n새는 하늘 높이 날고, 마차는 삐그덕 거리며, 말굽소리가 울","characters":["P-cf5685fee62d","P-542abe61bdc5"]},{"id":"RP-III-0092174","time":"2026-05-06T02:12:00+09:00","room":"RP III","name":"리스 / 제이","profile":"루체","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-cf5685fee62d","P-542abe61bdc5"]},{"id":"RP-III-0092175","time":"2026-05-06T02:12:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"다음을 기대할게..!","characters":[]}]};
